import{_ as o,g as r,o as s,c as d,j as a,a as n,k as i,a2 as c}from"./chunks/framework.DXa1R37q.js";const l={class:"diagram-links"},f=["href"],u={class:"diagram-frame blueprint"},p=["src"],_=JSON.parse('{"title":"Runtime and repository data flow","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"learn/runtime-data.md","filePath":"learn/runtime-data.md","lastUpdated":1793135521000}'),h={name:"learn/runtime-data.md"},v=Object.assign(h,{setup(m){const t=r("/diagrams/neottia-runtime.html");return(b,e)=>(s(),d("div",null,[e[0]||(e[0]=a("h1",{id:"runtime-and-repository-data-flow",tabindex:"-1"},[n("Runtime and repository data flow "),a("a",{class:"header-anchor",href:"#runtime-and-repository-data-flow","aria-label":'Permalink to "Runtime and repository data flow"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Pi and OpenCode normally load native extension packages. Claude Code and other MCP clients launch stdio servers. Both routes reach the same Memory, Issues, Design Docs, and Searchable domain tools.",-1)),a("div",l,[a("a",{href:i(t),target:"_blank",rel:"noreferrer"},"Open the interactive data-flow diagram in a new tab",8,f)]),a("div",u,[a("iframe",{src:i(t),title:"Interactive Neottia runtime and repository data-flow diagram",loading:"lazy"},null,8,p)]),e[2]||(e[2]=c('<h2 id="two-runtime-routes" tabindex="-1" data-v-70fc83a0>Two runtime routes <a class="header-anchor" href="#two-runtime-routes" aria-label="Permalink to &quot;Two runtime routes&quot;" data-v-70fc83a0>​</a></h2><ul data-v-70fc83a0><li data-v-70fc83a0><strong data-v-70fc83a0>Native extension route</strong> — Pi or OpenCode loads a Neottia package in process and calls the domain library directly.</li><li data-v-70fc83a0><strong data-v-70fc83a0>Generic MCP route</strong> — Claude Code or another compatible client launches a stdio server, which validates the MCP request and calls the same domain library.</li></ul><p data-v-70fc83a0>Do not enable both routes for the same capability in one host. Duplicate registrations can make ownership and cleanup ambiguous.</p><h2 id="one-write-authority" tabindex="-1" data-v-70fc83a0>One write authority <a class="header-anchor" href="#one-write-authority" aria-label="Permalink to &quot;One write authority&quot;" data-v-70fc83a0>​</a></h2><p data-v-70fc83a0>Domain packages do not publish repository files with ad hoc writes. Repository Store provides:</p><ul data-v-70fc83a0><li data-v-70fc83a0>path confinement and ancestor revalidation;</li><li data-v-70fc83a0>leases and exact identity checks;</li><li data-v-70fc83a0>no-replace publication;</li><li data-v-70fc83a0>preconditions and revision checks;</li><li data-v-70fc83a0>transaction journals and crash recovery;</li><li data-v-70fc83a0>file and namespace durability barriers.</li></ul><p data-v-70fc83a0>Unsupported runtimes and filesystems fail closed. Use <a href="/projects/neottia/operate/doctor" data-v-70fc83a0>Doctor</a> in the actual project directory before relying on filesystem-backed capabilities.</p><h2 id="canonical-and-disposable-state" tabindex="-1" data-v-70fc83a0>Canonical and disposable state <a class="header-anchor" href="#canonical-and-disposable-state" aria-label="Permalink to &quot;Canonical and disposable state&quot;" data-v-70fc83a0>​</a></h2><p data-v-70fc83a0>Track canonical records:</p><ul data-v-70fc83a0><li data-v-70fc83a0><code data-v-70fc83a0>.neottia/memory/...</code> YAML records;</li><li data-v-70fc83a0><code data-v-70fc83a0>.neottia/issues/...</code> YAML issue files;</li><li data-v-70fc83a0><code data-v-70fc83a0>.neottia/design-docs/...</code> Markdown documents;</li><li data-v-70fc83a0><code data-v-70fc83a0>.neottia/searchable/pages/...</code> JSON page stashes.</li></ul><p data-v-70fc83a0>Ignore disposable state:</p><ul data-v-70fc83a0><li data-v-70fc83a0>Memory <code data-v-70fc83a0>index.db*</code> files;</li><li data-v-70fc83a0><code data-v-70fc83a0>.neottia/cache/</code> SQLite projections;</li><li data-v-70fc83a0><code data-v-70fc83a0>.neottia/repository-store/</code> leases, journals, and recovery control files.</li></ul><p data-v-70fc83a0>See <a href="/projects/neottia/guides/repository-files" data-v-70fc83a0>Repository files and Git</a> for exact ignore rules. See <a href="/projects/neottia/reference/diagrams" data-v-70fc83a0>diagram sources and attribution</a> for evidence and license details.</p>',13))]))}}),g=o(v,[["__scopeId","data-v-70fc83a0"]]);export{_ as __pageData,g as default};
